import { mulberry32, clamp, DEG } from './util.js';
import { padMultiplier } from './config.js';

const WORLD_WIDTH = 2600;   // metres
const SAMPLES = 257;        // 2^8 + 1, required by midpoint displacement

/**
 * A 1-D heightfield generated by midpoint displacement, with flat landing
 * pads carved into it. Heights are metres above an arbitrary datum; the
 * ship's altitude is always measured against heightAt(x).
 */
export class Terrain {
  constructor(heights, step, pads) {
    this.h = heights;
    this.step = step;
    this.pads = pads;
    this.width = (heights.length - 1) * step;
  }

  heightAt(x) {
    const t = clamp(x, 0, this.width) / this.step;
    const i = Math.min(this.h.length - 2, Math.floor(t));
    const f = t - i;
    return this.h[i] + (this.h[i + 1] - this.h[i]) * f;
  }

  /** Ground slope in degrees at x (positive = rising to the right). */
  slopeDegAt(x) {
    const d = this.step;
    const dy = this.heightAt(x + d) - this.heightAt(x - d);
    return Math.atan2(dy, 2 * d) * DEG;
  }

  /** The pad containing x, or null. */
  padAt(x) {
    for (const p of this.pads) {
      if (x >= p.x1 && x <= p.x2) return p;
    }
    return null;
  }

  /** The pad whose centre is nearest to x -- used for the HUD guidance arrow. */
  nearestPad(x) {
    let best = null, bestD = Infinity;
    for (const p of this.pads) {
      const d = Math.abs(p.cx - x);
      if (d < bestD) { bestD = d; best = p; }
    }
    return best;
  }

  minHeight() {
    let m = Infinity;
    for (const v of this.h) if (v < m) m = v;
    return m;
  }
}

export function generateTerrain(level, seed) {
  const rand = mulberry32(seed);
  const step = WORLD_WIDTH / (SAMPLES - 1);
  const h = new Float64Array(SAMPLES);

  // Midpoint displacement: craggy, self-similar, cheap.
  const relief = 90 * level.roughness;
  h[0] = 60 + rand() * relief;
  h[SAMPLES - 1] = 60 + rand() * relief;

  for (let span = SAMPLES - 1; span > 1; span >>= 1) {
    const half = span >> 1;
    // Displacement shrinks with each subdivision -> fractal dimension ~1.3.
    const amp = relief * (span / (SAMPLES - 1)) ** 0.85;
    for (let i = 0; i + span < SAMPLES; i += span) {
      h[i + half] = (h[i] + h[i + span]) / 2 + (rand() - 0.5) * amp;
    }
  }

  // Keep the surface inside a sane band so the camera never loses it.
  for (let i = 0; i < SAMPLES; i++) h[i] = clamp(h[i], 25, 40 + relief * 2.2);

  const pads = carvePads(h, step, level, rand);
  return new Terrain(h, step, pads);
}

/**
 * Flatten `level.pads` stretches of ground into landing pads, spread evenly
 * across the middle of the world with a little jitter so they never line up
 * the same way twice.
 */
function carvePads(h, step, level, rand) {
  const pads = [];
  const count = level.pads;
  const halfCells = Math.max(2, Math.round(level.padWidth / 2 / step));
  const usable = h.length - 1;
  const margin = Math.round(usable * 0.12);
  const slotSize = (usable - margin * 2) / count;

  for (let n = 0; n < count; n++) {
    const centre = Math.round(
      margin + slotSize * (n + 0.5) + (rand() - 0.5) * slotSize * 0.5
    );
    const i0 = clamp(centre - halfCells, 1, usable - 1);
    const i1 = clamp(centre + halfCells, 1, usable - 1);

    // Sit the pad on the lowest ground it spans, then blend the shoulders in
    // so a pad never ends in a vertical cliff.
    let y = Infinity;
    for (let i = i0; i <= i1; i++) y = Math.min(y, h[i]);
    for (let i = i0; i <= i1; i++) h[i] = y;

    const blend = 3;
    for (let k = 1; k <= blend; k++) {
      const t = k / (blend + 1);
      const a = i0 - k, b = i1 + k;
      if (a >= 0) h[a] = h[a] * t + y * (1 - t);
      if (b < h.length) h[b] = h[b] * t + y * (1 - t);
    }

    const x1 = i0 * step, x2 = i1 * step;
    pads.push({
      x1, x2, y,
      cx: (x1 + x2) / 2,
      width: x2 - x1,
      mult: padMultiplier(x2 - x1),
    });
  }
  return pads;
}
